from author import page,section as s
page('home','en','home','A clearer signal. A new possibility.','Artifactory connects sensing research with photonic design tools. Explore ArtiSense, AIFIELD and the evidence behind a company-level investment conversation.','SENSING × PHOTONIC DESIGN','Artifactory explores what light can help us understand — and builds the tools to design what comes next. Two connected projects. One company-level conversation.',[
s('thesis','From a physical question to an engineered answer.','Sensing begins with a difficult question: how can a small optical response become useful information? Photonic engineering asks another: how can we design and test the systems that produce that response?','ArtiSense and AIFIELD approach these questions from different directions. Their connection is a design workflow, not a shortcut around experimental validation.'),
s('artisense','ArtiSense','A proposed miniaturized chemical-sensing system that combines photonics with signal interpretation. The intended direction includes non-invasive measurement and wearable form factors; these remain research ambitions.','The supplied glucose example concerns optical feasibility and chip design. It does not establish measured glucose accuracy or clinical readiness.',links=['artisense','artisense-validation']),
s('aifield','AIFIELD','Photonic CAD and simulation tooling for exploring geometry, layers and physical behavior. The September 2026 material describes classical simulation work and partially assisted engineering workflows.','Neural optical-field prediction is a separate research direction. Its assumptions and unresolved questions remain visible alongside the engineering tools.',links=['aifield','aifield-validation']),
s('evidence','Progress deserves a precise description.','A design answers a design question. A simulation tests a model under assumptions. Neither, on its own, demonstrates the behavior of a fabricated sensing device. Our project pages keep these evidence categories separate.',rows=[['ArtiSense · research','Optical feasibility and photonic chip-design work; physical sensing validation remains to be established.'],['AIFIELD · September 2026 snapshot','Design and classical-simulation examples; neural field research retains boundary-condition and generalization limits.']],links=['approach']),
s('conversation','Invest in the questions worth answering.','Explore the roles of both projects, what the available work supports, and which milestones would reduce the next uncertainty. The investment discussion is about Artifactory as a company.','For technical partners, the conversation can begin with sensing experiments, fabrication and measurement, or evaluation of the photonic design workflow.',links=['investors','about','partnerships'])],['investors','projects','about','partnerships'],visual='company')
page('home','pl','home','Czytelniejszy sygnał. Nowe możliwości.','Artifactory łączy badania nad pomiarami z narzędziami projektowania fotoniki. Poznaj ArtiSense, AIFIELD i podstawy rozmowy o inwestycji w firmę.','POMIARY × PROJEKTOWANIE FOTONIKI','Artifactory bada, co możemy zrozumieć dzięki światłu — i rozwija narzędzia do projektowania kolejnych rozwiązań. Dwa powiązane projekty. Rozmowa o jednej firmie.',[
s('thesis','Od pytania o zjawisko do rozwiązania inżynierskiego.','Pomiary zaczynają się od trudnego pytania: jak przekształcić niewielką odpowiedź optyczną w użyteczną informację? Inżynieria fotoniczna stawia kolejne: jak zaprojektować i sprawdzić system, który tę odpowiedź wytwarza?','ArtiSense i AIFIELD podchodzą do tych pytań z różnych stron. Łączy je proces projektowy, który nie zastępuje walidacji eksperymentalnej.'),
s('artisense','ArtiSense','Proponowany zminiaturyzowany system pomiaru składu chemicznego, łączący fotonikę z interpretacją sygnałów. Zamierzony kierunek obejmuje pomiary nieinwazyjne i formy ubieralne; pozostają one ambicjami badawczymi.','Opisany przykład dotyczący glukozy obejmuje wykonalność optyczną i projektowanie chipu. Nie potwierdza zmierzonej dokładności pomiaru glukozy ani gotowości klinicznej.',links=['artisense','artisense-validation']),
s('aifield','AIFIELD','Narzędzia CAD i symulacji fotonicznej do analizy geometrii, warstw i zjawisk fizycznych. Materiały z września 2026 opisują klasyczne symulacje oraz częściowo wspomagane procesy inżynierskie.','Neuronowe przewidywanie pola optycznego to odrębny kierunek badawczy. Jego założenia i otwarte pytania pozostają widoczne obok opisu narzędzi inżynierskich.',links=['aifield','aifield-validation']),
s('evidence','Postęp wymaga precyzyjnego opisu.','Projekt odpowiada na pytanie projektowe. Symulacja sprawdza model przy określonych założeniach. Żadne z nich samo w sobie nie pokazuje działania wykonanego urządzenia pomiarowego. Na stronach projektów rozdzielamy te kategorie dowodów.',rows=[['ArtiSense · badania','Prace nad wykonalnością optyczną i projektem chipu fotonicznego; fizyczna walidacja pomiaru pozostaje do ustalenia.'],['AIFIELD · stan z września 2026','Przykłady projektowania i klasycznych symulacji; badania neuronowe zachowują ograniczenia warunków brzegowych i uogólniania.']],links=['approach']),
s('conversation','Inwestycja zaczyna się od właściwych pytań.','Poznaj rolę obu projektów, zakres dostępnych dowodów i kamienie milowe, które mogłyby ograniczyć kolejne niewiadome. Rozmowa inwestycyjna dotyczy Artifactory jako firmy.','Z partnerami technicznymi możemy zacząć od tematu eksperymentów pomiarowych, wytwarzania i testów lub oceny procesu projektowania fotoniki.',links=['investors','about','partnerships'])],['investors','projects','about','partnerships'],visual='company')
